import java.util.*;

class Solution {
    public TreeNode invertTree(TreeNode root) {
        if (root == null) return null;
        TreeNode left = invertTree(root.left);   // mirror both sides first
        TreeNode right = invertTree(root.right);
        root.left = right;                       // then swap them
        root.right = left;
        return root;
    }
}

